/**
 * Pick the best Gen 2 era illustration for `species`. If a Gen 2 card
 * does not exist (Mr. Mime is the only such case at present), falls back
 * to the Gen 1 WotC art so all Kanto species still resolve.
 */
export function gen2CardArt(species: number): string | null {
  return GEN2_CARD_ART[species] ?? GEN1_CARD_ART[species] ?? null;
}
